def stage_read(path,expected):
 path=Path(path);require(path.is_absolute()and path.resolve()==path,'EXACT_STAGE_PATH_REQUIRED')
 fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
 try:
  first=os.fstat(fd);require(stat.S_ISREG(first.st_mode)and first.st_nlink==1 and 0<first.st_size<=262144,'BOUNDED_STAGE_FILE_REQUIRED')
  raw=os.read(fd,262145)
  pin=lambda st:tuple(getattr(st,k)for k in('st_dev','st_ino','st_mode','st_uid','st_gid','st_size','st_nlink','st_mtime_ns','st_ctime_ns'))
  require(len(raw)==first.st_size and pin(first)==pin(os.fstat(fd))==pin(path.lstat())and sha(raw)==expected,'STAGE_BYTES_CHANGED')
  return raw
 finally:os.close(fd)

